// Typed calls to the Rust commands. Types come from src/lib/bindings, generated by ts-rs from
// the Rust structs; nothing here is a second hand-written copy of the contract.
import { invoke } from '@tauri-apps/api/core';
import type { ConnectionView } from '#lib/bindings/ConnectionView.ts';
import type { ExportFormat } from '#lib/bindings/ExportFormat.ts';
import type { ExportWhat } from '#lib/bindings/ExportWhat.ts';
import type { LibraryEntry } from '#lib/bindings/LibraryEntry.ts';
import type { Settings } from '#lib/bindings/Settings.ts';
import type { SyncStatus } from '#lib/bindings/SyncStatus.ts';
import type { UserDataSummary } from '#lib/bindings/UserDataSummary.ts';
import type { WishlistEntry } from '#lib/bindings/WishlistEntry.ts';
import type { BatchView } from '#lib/bindings/BatchView.ts';
import type { DiaryRow } from '#lib/bindings/DiaryRow.ts';
import type { PlayView } from '#lib/bindings/PlayView.ts';
import type { ProductId } from '#lib/bindings/ProductId.ts';
import type { ProductTime } from '#lib/bindings/ProductTime.ts';
import type { Suggestion } from '#lib/bindings/Suggestion.ts';

/** States of a play, in board order. Same list as `plays::STATES` in Rust. */
export const PLAY_STATES = ['playing', 'backlog', 'paused', 'completed', 'dropped'] as const;
export type PlayState = (typeof PLAY_STATES)[number];

export type Provider = 'steam' | 'gog' | 'epic';

/** Error shape of the store commands: a stable code and a message already in Spanish. */
export type CommandError = { code: string; message: string };

export function asCommandError(e: unknown): CommandError {
	if (e && typeof e === 'object' && 'code' in e && 'message' in e) {
		return { code: String(e.code), message: String(e.message) };
	}
	return { code: 'internal', message: String(e) };
}

export const ipc = {
	connections: () => invoke<ConnectionView[]>('connections_list'),
	library: () => invoke<LibraryEntry[]>('library_list'),
	wishlist: () => invoke<WishlistEntry[]>('wishlist_list'),
	syncStatus: () => invoke<SyncStatus[]>('sync_status_list'),
	connect: (p: Provider) =>
		invoke<{ connected: boolean; account_changed: boolean }>(`${p}_connect`),
	disconnect: (p: Provider) => invoke<void>(`${p}_disconnect`),
	/** Epic syncs its library only: its wishlist is not available in this version. */
	sync: (p: Provider) => invoke<{ account_changed: boolean }>(`${p}_sync`),
	settings: () => invoke<Settings>('settings_get'),
	saveSettings: (settings: Settings) => invoke<Settings>('settings_set', { settings }),
	exportData: (what: ExportWhat, format: ExportFormat, path: string) =>
		invoke<number>('export_data', { what, format, path }),
	openDataFolder: () => invoke<void>('data_open_folder'),
	/** Ajustes › My data. Never carries connections, secrets or cleanup batches. */
	userdataExport: (path: string) => invoke<UserDataSummary>('userdata_export', { path }),
	userdataPreview: (path: string) => invoke<UserDataSummary>('userdata_preview', { path }),
	/** Replaces the user data with the file's, after a copy of the current one. */
	userdataImport: (path: string) => invoke<UserDataSummary>('userdata_import', { path }),
	clearCache: () => invoke<void>('data_clear_cache'),
	plans: () => invoke<BatchView[]>('plans_list'),
	planCreate: (store: string, accountId: string, nativeIds: string[]) =>
		invoke<BatchView>('plan_create', { store, accountId, nativeIds }),
	planConfirm: (batchId: string, revision: string) =>
		invoke<BatchView>('plan_confirm', { batchId, revision }),
	planReconcile: (batchId: string) => invoke<BatchView>('plan_reconcile', { batchId }),
	planDiscard: (batchId: string) => invoke<void>('plan_discard', { batchId }),
	/** Sends a confirmed batch of a store whose write is validated (GOG). */
	planExecute: (batchId: string) => invoke<BatchView>('plan_execute', { batchId }),
	/** Cancels what a confirmed batch has not sent yet. */
	planCancel: (batchId: string) => invoke<BatchView>('plan_cancel', { batchId }),
	/** Puts the failed entries of a finished batch back to pending; send them with planExecute. */
	planRetry: (batchId: string) => invoke<BatchView>('plan_retry', { batchId }),
	plays: () => invoke<PlayView[]>('plays_list'),
	/** Creates or moves a play: top of `state`, just ahead of `before` in it, or its end. */
	playSet: (store: string, nativeId: string, state: PlayState, before?: ProductId, end = false) =>
		invoke<PlayView[]>('play_set', { store, nativeId, state, before: before ?? null, end }),
	playNote: (store: string, nativeId: string, note: string) =>
		invoke<void>('play_note', { store, nativeId, note }),
	playRemove: (store: string, nativeId: string) => invoke<void>('play_remove', { store, nativeId }),
	suggestions: () => invoke<Suggestion[]>('suggestions_list'),
	diary: () => invoke<DiaryRow[]>('diary_list'),
	/** Play time of a sheet's products from the cache. GOG is asked apart with `gogPlaytime`. */
	playtimeOf: (products: ProductId[]) => invoke<ProductTime[]>('playtime_of', { products }),
	/** Stores that give play time in this build (Epic and GOG only once validated). */
	playtimeStores: () => invoke<string[]>('playtime_stores'),
	/** "Descartar": the suggestion of `target` for this product does not come back. */
	suggestionDismiss: (store: string, nativeId: string, target: 'playing' | 'paused') =>
		invoke<void>('suggestion_dismiss', { store, nativeId, target }),
	/** Minutes played of one GOG product, asked when its sheet opens; `null`: GOG does not give it. */
	gogPlaytime: (nativeId: string) => invoke<number | null>('gog_playtime', { nativeId })
};
